(()=>{
  const endpoint='https://ras-crww-comments.cosmicflea4.chatgpt.site/api/comments';
  const form=document.querySelector('#comment-form'),list=document.querySelector('#comment-list'),status=document.querySelector('#comment-status'),submit=form.querySelector('[type=submit]'),more=document.querySelector('#comment-more');
  let token='',owned=new Set(),cursor=0,busy=false;
  try{token=localStorage.getItem('ras-comment-token')||'';owned=new Set(JSON.parse(localStorage.getItem('ras-my-comments')||'[]'));form.elements.name.value=localStorage.getItem('ras-comment-name')||''}catch{}
  function save(){try{localStorage.setItem('ras-comment-token',token);localStorage.setItem('ras-my-comments',JSON.stringify([...owned]));localStorage.setItem('ras-comment-name',form.elements.name.value.trim())}catch{}}
  async function request(path='',options={}){const response=await fetch(endpoint+path,{signal:AbortSignal.timeout(15000),...options,headers:{...options.headers}});let data;try{data=await response.json()}catch{throw new Error('留言服务暂时不可用，请稍后重试。')}if(!response.ok){const error=new Error(data.error||'操作失败，请稍后再试。');error.code=data.code;throw error}return data}
  async function session(){if(token)return;const data=await request('?session=new');token=data.token;save()}
  function renderComment(item){const article=document.createElement('article');article.className='comment-entry';article.dataset.id=item.id;const avatar=document.createElement('span');avatar.className='comment-avatar';avatar.textContent=Array.from(item.name)[0]||'夜';const main=document.createElement('div');main.className='comment-main';const head=document.createElement('div');head.className='comment-entry-heading';const name=document.createElement('strong');name.textContent=item.name;const time=document.createElement('time');time.dateTime=new Date(item.created_at).toISOString();time.textContent=new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(item.created_at));head.append(name,time);if(owned.has(item.id)){const remove=document.createElement('button');remove.className='comment-delete';remove.textContent='删除';remove.setAttribute('aria-label','删除我的这条留言');remove.onclick=async()=>{remove.disabled=true;try{await request('?id='+encodeURIComponent(item.id),{method:'DELETE',headers:{Authorization:'Bearer '+token}});owned.delete(item.id);save();await load()}catch(error){status.textContent=error.message;remove.disabled=false}};head.append(remove)}const body=document.createElement('p');body.textContent=item.body;main.append(head,body);article.append(avatar,main);return article}
  async function load(append=false){if(busy)return;busy=true;more.disabled=true;try{const data=await request(append?'?before='+cursor:'');if(!append)list.replaceChildren();data.comments.forEach(item=>list.append(renderComment(item)));if(data.comments.length)cursor=data.comments.at(-1).created_at;document.querySelector('#comment-count').textContent=data.total+' 条留言';more.hidden=!data.hasMore;document.querySelector('#comment-empty').hidden=data.total>0;status.textContent=''}catch(error){status.textContent=error.message}finally{busy=false;more.disabled=false}}
  more.onclick=()=>load(true);document.querySelector('#comment-refresh').onclick=()=>load();
  form.elements.body.addEventListener('input',()=>{document.querySelector('#comment-length').textContent=form.elements.body.value.length+' / 1200'});
  form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;submit.disabled=true;submit.classList.add('is-loading');status.textContent='正在把留言送进夜里…';const payload={name:form.elements.name.value.trim(),body:form.elements.body.value.trim(),website:form.elements.website.value};try{await session();let data;try{data=await request('',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(payload)})}catch(error){if(error.code!=='SESSION')throw error;token='';await session();data=await request('',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(payload)})}owned.add(data.comment.id);save();form.elements.body.value='';document.querySelector('#comment-length').textContent='0 / 1200';while(busy)await new Promise(resolve=>setTimeout(resolve,50));await load();status.textContent='留言已送达，刷新后也会在这里。'}catch(error){status.textContent=error.message}finally{submit.disabled=false;submit.classList.remove('is-loading')}};
  const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){load();observer.disconnect()}},{rootMargin:'300px'});observer.observe(document.querySelector('#comments'));
})();
